-- Who asked for a continuation job (`continuations.asked_by`, JSON) is
-- columns of its row: `asked_by_kind`, `asked_by_id` (the session or task
-- that asked) and, for a move, its own fields as JSON in `asked_by_move`
-- (its line, the move, what stopped it, the account it goes to). Whether a
-- job folds into its source (continuations.ts `openTarget`: anything but
-- the person's) and which job is a session's move (limit-moves.ts
-- `moveJobOf`) are read off `asked_by_kind`, by the index on its source and
-- kind. A job's wait (`continuations.waiting`) is `waiting_from` (since
-- when the job waited, its bound counting from then), `waiting_since`
-- (since when the work it waits for ran; null when not known) and
-- `waiting_why`.
--
-- `asked_by` was NOT NULL, `{"kind":"person"}` by default: an asker never
-- set is the person's, and reads so. An asker that reads whole (one of the
-- four, every part of its shape: db/continuation-askers-unread.ts `ASKER`)
-- is placed as it is: its kind, its id, a move's fields less its kind. A
-- wait never set (null) is no wait; one that reads whole is placed as it
-- is. Nothing is recomputed.
--
-- An asker that is there and does not read whole (not JSON, or no asker
-- whole) is kept as stored in `asked_by_unread`, and the job is the
-- person's: never folded into its source, never its source's move, nothing
-- else of it placed. An open one fails as the hub starts, its source going
-- on as it was (continuations.ts `unreadAskersFail`). A wait that does not
-- read whole is kept in `waiting_unread`, none of it placed: the job's
-- bound counts from when it next looks, so it never ends work in flight
-- sooner. Today's reader threw on either. The step before this migration
-- (db/migrate.ts `continuations-unread`) logs each by its job and why.
--
-- Every JSON function sits inside a CASE that proved its column JSON:
-- SQLite may run either side of an AND first.
ALTER TABLE `continuations` ADD `asked_by_kind` text DEFAULT 'person' NOT NULL;--> statement-breakpoint
ALTER TABLE `continuations` ADD `asked_by_id` text;--> statement-breakpoint
ALTER TABLE `continuations` ADD `asked_by_move` text;--> statement-breakpoint
ALTER TABLE `continuations` ADD `asked_by_unread` text;--> statement-breakpoint
ALTER TABLE `continuations` ADD `waiting_from` integer;--> statement-breakpoint
ALTER TABLE `continuations` ADD `waiting_since` integer;--> statement-breakpoint
ALTER TABLE `continuations` ADD `waiting_why` text;--> statement-breakpoint
ALTER TABLE `continuations` ADD `waiting_unread` text;--> statement-breakpoint
UPDATE `continuations` SET `asked_by_unread` = CASE WHEN CASE WHEN json_valid(asked_by) THEN coalesce(((json_type(asked_by, '$') IN ('object') AND (json_type(asked_by, '$.kind') IN ('text') AND (json_type(asked_by, '$.kind') = 'text' AND json_extract(asked_by, '$.kind') = 'person'))) OR (json_type(asked_by, '$') IN ('object') AND (json_type(asked_by, '$.kind') IN ('text') AND (json_type(asked_by, '$.kind') = 'text' AND json_extract(asked_by, '$.kind') = 'session')) AND (json_type(asked_by, '$.id') IN ('text'))) OR (json_type(asked_by, '$') IN ('object') AND (json_type(asked_by, '$.kind') IN ('text') AND (json_type(asked_by, '$.kind') = 'text' AND json_extract(asked_by, '$.kind') = 'task')) AND (json_type(asked_by, '$.id') IN ('text'))) OR (json_type(asked_by, '$') IN ('object') AND (json_type(asked_by, '$.kind') IN ('text') AND (json_type(asked_by, '$.kind') = 'text' AND json_extract(asked_by, '$.kind') = 'move')) AND (json_type(asked_by, '$.line') IN ('text')) AND ((json_type(asked_by, '$.move') IN ('object') AND (json_type(asked_by, '$.move.kind') IN ('text') AND (json_type(asked_by, '$.move.kind') = 'text' AND json_extract(asked_by, '$.move.kind') = 'moved')) AND (json_type(asked_by, '$.move.from') IN ('object') AND (json_type(asked_by, '$.move.from.hue') IN ('text') AND (json_type(asked_by, '$.move.from.hue') = 'text' AND json_extract(asked_by, '$.move.from.hue') IN ('amber', 'blue', 'cyan', 'green', 'orange', 'rose', 'violet'))) AND (json_type(asked_by, '$.move.from.id') IN ('text')) AND (json_type(asked_by, '$.move.from.name') IN ('text'))) AND (json_type(asked_by, '$.move.to') IN ('object') AND (json_type(asked_by, '$.move.to.hue') IN ('text') AND (json_type(asked_by, '$.move.to.hue') = 'text' AND json_extract(asked_by, '$.move.to.hue') IN ('amber', 'blue', 'cyan', 'green', 'orange', 'rose', 'violet'))) AND (json_type(asked_by, '$.move.to.id') IN ('text')) AND (json_type(asked_by, '$.move.to.name') IN ('text'))) AND (json_type(asked_by, '$.move.sameOrganizati